+/// Conditional statements with an else can supply a block's value. Without
+/// one they remain statements in an optional-value arm; a required branch
+/// goes to the value judge regardless, so that judge names the missing else.
+fn block_tail_can_place_value(c Node) -> bool {
+    ro k = c.kind_of()
+    if k == NodeKind.IfStmt { return branch_children(c).len() >= 5 }
+    if k == NodeKind.IfLet {
+        ro kids = branch_children(c)
+        return kids.len() > iflet_else_at(kids)
+    }
+    is_value_tail_kind(k)
+}
