+/// Type one block tail through its value door, not its statement spelling.
+/// The recorded answer is what lower reads; an inner refusal stops the
+/// lattice query, including a literal that did not fit the expected width.
+fn Checker mut @type_block_value_tail(c Node) -> TyId {
+    ro before = @out.len()
+    ro lit_t = @branch_literal_tail(c)
+    if is_ty(lit_t) || @out.len() > before { return lit_t }
+    ro k = c.kind_of()
+    if k == NodeKind.IfStmt || k == NodeKind.IfExpr {
+        @type_if_value(c)
+        if @out.len() > before { return no_ty() }
+        return @chan.type_if_known(c.id_of())
+    } else if k == NodeKind.IfLet {
+        @type_if_let(c, as_value: true)
+        if @out.len() > before { return no_ty() }
+        return @chan.type_if_known(c.id_of())
+    } else if is_value_tail_kind(k) {
+        @type_expr(c)
+        if @out.len() > before { return no_ty() }
+        return type_of(c, @ctx, @scope, @chan)
+    } else {
+        @report_first_leaf_of([]Node.of(c), "outside the subset: a branch of a tail `if` ends without a value (E2-b)")
+    }
+    no_ty()
